# AI generated by: Claude Code / claude-opus-5-5
# Prompt: "could you allocate 8cpus and 4GB of memory at base, also after the tests run, make sure the output is printed out into the console formatted and the vm is stopped."
# Changes: Print a compact, colored report of the e2e/memory summaries written during this run.
"""Usage: python3 report.py MARKER BUILD_TESTS_DIR

Prints every summary in BUILD_TESTS_DIR that is newer than MARKER, so stale
summaries from earlier runs are skipped.
"""
import os
import shutil
import sys
from pathlib import Path

COLOR = sys.stdout.isatty() and "NO_COLOR" not in os.environ
WIDTH = shutil.get_terminal_size((100, 20)).columns


def paint(text, code):
    return f"\033[{code}m{text}\033[0m" if COLOR else text


def heading(title):
    bar = "=" * max(0, WIDTH - len(title) - 4)
    print(f"\n{paint(f'== {title} {bar}', '1;36')}")


def clip(text, indent):
    room = max(20, WIDTH - indent)
    return text if len(text) <= room else text[: room - 3] + "..."


def status_line(line):
    if ": FAIL" in line or line.startswith("FAIL") or (" failed" in line and " 0 failed" not in line):
        return paint(line, "31")
    if "PASS" in line or " 0 failed" in line:
        return paint(line, "32")
    return line


def report_e2e(path):
    blocks = path.read_text().split("\n\n")
    heading("e2e summary")
    for line in blocks[0].splitlines()[1:]:
        print("  " + status_line(line))
    failures = []
    for block in blocks[1:]:
        lines = block.splitlines()
        if not lines:
            continue
        reasons = {}
        for line in lines[1:]:
            for mode, short in (("without optimizer", "off"), ("with optimizer", "on")):
                prefix = f"  {mode}: FAIL: "
                if line.startswith(prefix):
                    reasons[short] = line[len(prefix):]
        if reasons:
            failures.append((lines[0], reasons))
    if not failures:
        print("  " + paint("all cases passed", "32"))
        return True
    print(f"\n  {paint(f'Failed cases ({len(failures)}):', '1;31')}")
    for name, reasons in failures:
        if len(reasons) == 2 and reasons["off"] == reasons["on"]:
            reasons = {"both": reasons["off"]}
        print(f"  {paint(name, '1')}")
        for mode, reason in reasons.items():
            print(f"    {paint(mode.ljust(4), '33')} {clip(reason, 9)}")
    print(f"\n  details: {path}")
    return False


def report_memory(path):
    heading("memory summary")
    ok = True
    for line in path.read_text().splitlines()[1:]:
        ok &= not line.startswith("FAIL")
        print("  " + status_line(clip(line, 2)))
    return ok


def main():
    marker, tests = Path(sys.argv[1]).stat().st_mtime, Path(sys.argv[2])
    printed = False
    for name, show in (("e2e_summary.txt", report_e2e), ("memory_summary.txt", report_memory)):
        path = tests / name
        if path.is_file() and path.stat().st_mtime >= marker:
            show(path)
            printed = True
    if not printed:
        print(paint("\nNo test summaries were written (build failed?)", "33"))


if __name__ == "__main__":
    main()
